-- Table: "public"."MenuItem"
DROP TABLE IF EXISTS "public"."MenuItem" CASCADE;
CREATE TABLE "public"."MenuItem" (
  "id" integer NOT NULL DEFAULT nextval('"MenuItem_id_seq"'::regclass),
  "key" text NOT NULL,
  "icon" text NOT NULL,
  "label" text NOT NULL,
  "parentId" integer,
  "order" integer NOT NULL DEFAULT 0,
  "isVisible" boolean NOT NULL DEFAULT true,
  "requiredRoles" ARRAY DEFAULT ARRAY[]::text[],
  "menuType" USER-DEFINED NOT NULL DEFAULT 'MENU'::"MenuType",
  "perm" text,
  "path" text,
  "component" text,
  "createdAt" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp without time zone NOT NULL,
  PRIMARY KEY ("id")
);

