-- Table: "public"."MonthlyReport"
DROP TABLE IF EXISTS "public"."MonthlyReport" CASCADE;
CREATE TABLE "public"."MonthlyReport" (
  "id" integer NOT NULL DEFAULT nextval('"MonthlyReport_id_seq"'::regclass),
  "userId" integer NOT NULL,
  "year" integer NOT NULL,
  "month" integer NOT NULL,
  "summary" text NOT NULL,
  "achievements" text,
  "issues" text,
  "nextMonthPlan" text,
  "totalHours" numeric NOT NULL,
  "reportCount" integer NOT NULL,
  "status" USER-DEFINED NOT NULL DEFAULT 'DRAFT'::"ReportStatus",
  "deletedAt" timestamp without time zone,
  "createdAt" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp without time zone NOT NULL,
  PRIMARY KEY ("id")
);

-- Table: "public"."Notification"
DROP TABLE IF EXISTS "public"."Notification" CASCADE;
CREATE TABLE "public"."Notification" (
  "id" integer NOT NULL DEFAULT nextval('"Notification_id_seq"'::regclass),
  "userId" integer NOT NULL,
  "type" text NOT NULL,
  "taskId" integer,
  "message" text NOT NULL,
  "isRead" boolean NOT NULL DEFAULT false,
  "deletedAt" timestamp without time zone,
  "createdAt" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

