-- Table: "public"."OperationLog"
DROP TABLE IF EXISTS "public"."OperationLog" CASCADE;
CREATE TABLE "public"."OperationLog" (
  "id" integer NOT NULL DEFAULT nextval('"OperationLog_id_seq"'::regclass),
  "userId" integer,
  "userName" text,
  "module" text NOT NULL,
  "action" text NOT NULL,
  "target" text,
  "detail" text,
  "ip" text,
  "userAgent" text,
  "status" USER-DEFINED NOT NULL DEFAULT 'SUCCESS'::"LogStatus",
  "createdAt" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

