-- Table: "public"."WeeklyReport"
DROP TABLE IF EXISTS "public"."WeeklyReport" CASCADE;
CREATE TABLE "public"."WeeklyReport" (
  "id" integer NOT NULL DEFAULT nextval('"WeeklyReport_id_seq"'::regclass),
  "userId" integer NOT NULL,
  "weekStart" timestamp without time zone NOT NULL,
  "weekEnd" timestamp without time zone NOT NULL,
  "summary" text NOT NULL,
  "highlights" text,
  "issues" text,
  "nextWeekPlan" text,
  "totalHours" numeric NOT NULL,
  "reportCount" integer NOT NULL,
  "status" USER-DEFINED NOT NULL DEFAULT 'DRAFT'::"ReportStatus",
  "deletedAt" timestamp without time zone,
  "createdAt" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp without time zone NOT NULL,
  PRIMARY KEY ("id")
);

